import{_ as e,o as l,c as o,a3 as t}from"./chunks/framework.D1iekJsc.js";const h=JSON.parse('{"title":"安装 KoboldCPP","description":"安装 KoboldCPP，加载 GGUF，为 MiniTavern 提供 OpenAI 兼容 API（角色扮演常用）。","frontmatter":{"title":"安装 KoboldCPP","description":"安装 KoboldCPP，加载 GGUF，为 MiniTavern 提供 OpenAI 兼容 API（角色扮演常用）。","head":[["meta",{"name":"keywords","content":"酒馆,AI酒馆,Ai酒馆,迷你酒馆,超迷你酒馆,MiniTavern,AI伙伴,AI朋友,Ai本地聊天,AI本地聊天,Silly Tavern,SillyTavern,手机玩Silly Tavern,Silly Tavern手机版,Silly Tavern安卓,Silly Tavern苹果,AI角色扮演,角色卡,角色扮演,AI聊天,手机AI,离线AI,AI剧情,本地大模型,本地模型,Ollama,LM Studio,世界书,正则,BYOK,用户手册,教程,character card,AI roleplay,AI companion,tavern AI"}],["meta",{"property":"og:title","content":"安装 KoboldCPP · MiniTavern Docs"}],["meta",{"property":"og:description","content":"安装 KoboldCPP，加载 GGUF，为 MiniTavern 提供 OpenAI 兼容 API（角色扮演常用）。"}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/koboldcpp/install"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/koboldcpp/install"}]]},"headers":[],"relativePath":"koboldcpp/install.md","filePath":"koboldcpp/install.md","lastUpdated":1786329914000}'),i={name:"koboldcpp/install.md"};function n(r,a,d,s,p,c){return l(),o("div",null,[...a[0]||(a[0]=[t('<h1 id="安装与上手-koboldcpp" tabindex="-1">安装与上手（KoboldCPP） <a class="header-anchor" href="#安装与上手-koboldcpp" aria-label="Permalink to &quot;安装与上手（KoboldCPP）&quot;">​</a></h1><p><a href="https://github.com/LostRuins/koboldcpp" target="_blank" rel="noreferrer">KoboldCPP</a> 基于 llama.cpp，带轻量界面，在角色扮演社区很常见，可开启 <strong>OpenAI 兼容</strong> HTTP API，供 MiniTavern 连接。</p><h2 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to &quot;安装&quot;">​</a></h2><ol><li>打开 GitHub Releases，按系统下载对应构建（Windows 常有独立 <code>.exe</code>；其它系统按说明编译或使用发布包）。</li><li>首次运行按提示选择后端（CUDA / Metal / Vulkan / CPU 等），以你硬件为准。</li><li>准备一个 <strong>GGUF</strong> 模型文件（见 <a href="/ultra_guides/local/models">推荐模型</a>）。</li></ol><h2 id="加载模型" tabindex="-1">加载模型 <a class="header-anchor" href="#加载模型" aria-label="Permalink to &quot;加载模型&quot;">​</a></h2><ol><li>在 KoboldCPP 中选择模型文件并启动。</li><li>确认能在其自带聊天或 UI 里正常生成，再开对外 API。</li><li>记下你使用的上下文长度、GPU 层数等；先用默认能跑通即可。</li></ol><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p><a href="./server">开启 API / 局域网</a> → <a href="/ultra_guides/connect-app/minitavern">在 MiniTavern 中配置</a></p>',8)])])}const b=e(i,[["render",n]]);export{h as __pageData,b as default};
